-- US TWO superdate upgrade: preserve milestone protocol, 72-hour lock and existing games.
-- Private template table cannot be read through the browser Data API.
CREATE TABLE IF NOT EXISTS us_two_private.quest_superdate_templates (
 idx smallint PRIMARY KEY CHECK (idx BETWEEN 1 AND 18),
 title text NOT NULL,
 prep_a text NOT NULL,
 prep_b text NOT NULL,
 finale_together text NOT NULL,
 finale_remote text NOT NULL
);
ALTER TABLE us_two_private.quest_superdate_templates ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE us_two_private.quest_superdate_templates FROM PUBLIC, anon, authenticated;
INSERT INTO us_two_private.quest_superdate_templates (idx,title,prep_a,prep_b,finale_together,finale_remote)
SELECT idx,title,prep_a,prep_b,finale_together,finale_remote
FROM jsonb_to_recordset($US_TWO_SUPER$[{"idx":1,"title":"Het Geheime Complimentenfestival","prep_a":"Schrijf zes verschillende complimentkaartjes die gaan over gedrag, humor of zorgzaamheid. Verstop er drie in envelopjes, teken er symbolen bij en bewaar alles tot jullie allebei toestemming geven.","prep_b":"Bedenk drie vriendelijke prijsuitreikingen, bijvoorbeeld 'koning van de gekke plannen'. Maak van papier kleine prijzen en bereid een korte openingsspeech voor zonder de ander iets te verklappen.","finale_together":"Open samen het complimentenfestival: houd drie rondes waarin de een een verborgen compliment voorleest en de ander een prijs uitreikt. Wissel rollen, kies een grappige festivalnaam en bewaar één kaartje als herinnering.","finale_remote":"Maak via video drie festivalrondes. De een laat steeds een complimentkaartje zien; de ander presenteert een zelfgemaakte prijs. Stuur achteraf vrijwillig één foto van je creatie."},{"idx":2,"title":"De Grote Thuisdate","prep_a":"Richt zonder nieuwe aankopen een fijne datehoek in met licht, een zitplaats en een drankje. Bedenk twee verrassende gespreksvragen en één klein gezamenlijk startmoment, maar vertel nog niets.","prep_b":"Maak twee kaartjes voor speelse activiteiten van maximaal tien minuten. Bereid daarnaast een eenvoudige afsluiting voor, zoals een foto op een vaste plek of een korte eigen dans.","finale_together":"Start met de verborgen inrichting, laat de ander de twee activiteitenkaartjes kiezen en wissel de rollen van gastheer en gast. Sluit af met het afgesproken ritueel, zonder prestatiedruk.","finale_remote":"Richt allebei een hoekje in op de eigen plek, toon het via video, trek beurtelings een activiteitenkaartje en eindig met dezelfde symbolische handeling op afstand."},{"idx":3,"title":"Het Portaalfeest","prep_a":"Ontwerp een papieren toegangspoort naar jullie nieuwe wereld. Bedenk drie symbolen die bij de wereld passen en schrijf één raadsel dat de ander door het portaal moet oplossen.","prep_b":"Maak een geheime welkomstceremonie: kies een passende maar comfortabele outfit, bedenk een naam voor de nieuwe wereld en bereid een feestelijke openingszin voor.","finale_together":"Laat het portaal zien en voer eerst het raadsel uit. De ander opent de wereld met de welkomswoorden, daarna kiezen jullie samen een vlag, een dansbeweging en een naam voor jullie volgende avontuur.","finale_remote":"Laat elkaar via video de poort en kleding zien. Los het raadsel op, spreek allebei de welkomstwoorden en ontwerp samen een digitale vlag voor de nieuwe wereld."},{"idx":4,"title":"De Absurdste Talentenavond","prep_a":"Kies twee totaal onschuldige talenten die je bijna nooit laat zien, zoals achterstevoren tellen of geluiden nadoen. Bereid een korte openingsact voor zonder jezelf te forceren.","prep_b":"Bedenk een komische presentatorrol met drie originele aankondigingen en twee vrolijke publieksprijzen die niet met winnen of verliezen te maken hebben.","finale_together":"Open de talentenshow met de presentator en voer beurtelings twee mini-acts op. Geef na elke act een zelfgemaakte vriendelijke prijs en sluit af met een gezamenlijke finaleact.","finale_remote":"Organiseer via videogesprek dezelfde show: elk doet twee acts, de ander presenteert een aankondiging en geeft een vrolijke symbolische prijs."},{"idx":5,"title":"Mini-Festival voor Twee","prep_a":"Ontwerp drie oorspronkelijke mini-optredens met eigen ritmes, korte grapjes of bewegingen. Kies een simpele volgorde en schrijf op papier een geheime festivalprogrammering.","prep_b":"Maak een fictief festivalterrein op papier, teken toegangskaartjes en bedenk drie plekken: podium, rusthoek en verrassingskraam. Maak een passende dresscode die vrijwillig is.","finale_together":"Open samen het papieren festival, ruil de kaartjes en voer de drie mini-acts uit. Wandel langs de getekende festivalplekken en maak samen één groepsfoto als festivalposter.","finale_remote":"Laat via video allebei je terreinontwerp zien. Presenteren en optreden gebeurt om de beurt; maak achteraf één gedeelde digitale festivalposter."},{"idx":6,"title":"Het Verborgen Eiland","prep_a":"Teken een geheime eilandkaart met drie herkenningspunten, een veilige schuilplek en een aanwijzing naar een symbolische schat. Laat de kaart pas tijdens de finale zien.","prep_b":"Maak een kleine 'overlevingskoffer' van drie gewone huishoudvoorwerpen. Bedenk bij elk voorwerp een originele functie en schrijf één geheim eilandverhaal.","finale_together":"Verbind de eilandkaart met de drie voorwerpen. Ga samen op een denkbeeldige tocht langs alle herkenningspunten, vind de schat en bedenk een gezamenlijke eilandnaam.","finale_remote":"Laat elkaar via video kaart en koffer zien. De eerste leidt de tocht met aanwijzingen, de ander lost de voorwerpraadsels op; maak samen een digitaal eilandenpaspoort."},{"idx":7,"title":"Mysteriepicknick","prep_a":"Bedenk drie eetbare of papieren 'proefclues' en schrijf bij elk een grappige aanwijzing. Houd rekening met eventuele allergieën en laat proeven altijd vrijblijvend.","prep_b":"Ontwerp een kleine picknickplek met spullen die er al zijn. Verstop in de opstelling drie vraagkaartjes die de ander pas tijdens de finale mag openen.","finale_together":"Combineer cluekaartjes met de drie verborgen vragen. Open na elke gevonden aanwijzing één gespreksonderwerp en sluit af met een gezamenlijke foto van jullie picknick.","finale_remote":"Maak op beide locaties een eigen picknickplek en onthul via video steeds een clue en een vraag. Eten is optioneel; beschrijf je fictieve favoriete snack als je niets wilt kopen."},{"idx":8,"title":"De Onmogelijke Vakantie","prep_a":"Schrijf een reisplan voor drie absurd mooie bestemmingen die niet echt kunnen bestaan. Geef elke bestemming een prijsloze belevenis en een raadsel als toegangsbewijs.","prep_b":"Ontwerp een fictief reisbureau met paspoortstempels op papier, een belachelijke vluchtomroep en één geheime excursie waarvoor geen spullen nodig zijn.","finale_together":"Check samen in bij het reisbureau, verzamel de stempels en bezoek de drie bestemmingen in de woonkamer. Los de raadsels op en sluit af met een gezamenlijke reisfoto.","finale_remote":"Gebruik een videogesprek als incheckbalie: om de beurt voert één van jullie de ander naar een fictieve bestemming en verdient die een digitale stempel."},{"idx":9,"title":"Onze Filmprijsuitreiking","prep_a":"Maak drie originele filmprijzen die verwijzen naar grappige gezamenlijke herinneringen. Teken de prijzen en bedenk bij elk een korte nominatie zonder kwetsende grappen.","prep_b":"Maak een rode-loper-interview met vijf vriendelijke vragen, een eigen openingsmuziekje van hoogstens tien seconden en een verrassende finale-aankondiging.","finale_together":"Loop samen over de geïmproviseerde rode loper, wissel interview en prijsuitreiking af en maak een foto van jullie zelfgemaakte filmprijzen.","finale_remote":"Maak ieder een rode-loper-achtergrond voor de camera, wissel vijf vragen uit en presenteer om de beurt de creatieve filmprijzen."},{"idx":10,"title":"De Regisseur van Ons Leven","prep_a":"Schrijf een origineel mini-filmscript met drie scènes: een onverwachte ontmoeting, een klein probleem en een mooi einde. Bedenk alvast een titel.","prep_b":"Verzamel veilige, gratis rekwisieten en ontwerp drie camerastandpunten. Maak een lijst met grappige regieaanwijzingen en een eindkaart voor de film.","finale_together":"Lees samen het script, kies rollen en film de drie scènes met de voorbereide camerastandpunten. Sluit af met de eindkaart en bekijk jullie eigen film.","finale_remote":"Film elk een of twee scènes op je eigen locatie. Combineer de opnames op volgorde en presenteer de mini-film tijdens een gezamenlijke videocall."},{"idx":11,"title":"Het Maskerbal","prep_a":"Maak van papier of via een digitale tekening twee eenvoudige maskers met een eigen karakter. Kies voor elk een fictieve naam en één kleine eigenaardigheid.","prep_b":"Schrijf een mysterieuze uitnodiging met drie hints over een denkbeeldige balzaal en bedenk twee vriendelijke vragen die gasten als geheime personages beantwoorden.","finale_together":"Open het maskerbal met de uitnodiging, speel ieder een fictief personage, raad elkaars karakter en onthul de maskers. Laat comfortabel meedoen altijd voorgaan.","finale_remote":"Zet de camera op voor een digitaal maskerbal, speel de personages en laat de ander via drie vragen je geheime identiteit raden."},{"idx":12,"title":"Tijdcapsule van Ons","prep_a":"Selecteer drie herinneringen die je vrijwillig wilt bewaren. Maak voor elke herinnering een tekening of korte tekst en stop de kaartjes in een envelop.","prep_b":"Bedenk drie toekomstwensen zonder deadlines of verplichting. Maak een eenvoudige omslag voor jullie capsule en schrijf een datum waarop je hem eventueel wilt openen.","finale_together":"Deel de herinneringen en toekomstwensen met elkaar, kies samen wat privé blijft en verzegel de envelop met een zelfgemaakt symbool. Bewaar hem op een afgesproken plek.","finale_remote":"Maak ieder een digitale envelop en laat de ander alleen zien wat je zelf wilt delen. Sla samen een openingsdatum op als vrijblijvende herinnering."},{"idx":13,"title":"De Geheime Wensenjacht","prep_a":"Schrijf drie kleine, haalbare wensen die niets moeten kosten. Verstop bij elke wens een korte hint en markeer waar de ander de volgende aanwijzing vindt.","prep_b":"Ontwerp een raadselroute met drie vriendelijke uitdagingen die veilig in huis kunnen worden uitgevoerd, zoals een tekening maken of een compliment uitspreken.","finale_together":"Speel de route in drie rondes, wissel tussen hint en wens en kies samen of jullie één wens direct willen uitvoeren. Overslaan mag altijd zonder uitleg.","finale_remote":"Stuur elkaar om de beurt een hint in de chat en los de drie raadsels via video op. Deel een wens alleen wanneer je dat zelf wilt."},{"idx":14,"title":"Onze Droomstad","prep_a":"Teken een stadskaart met drie buurten die passen bij jullie favoriete hobby's. Geef elke buurt een eigen naam en bedenk een onverwachte ontmoetingsplek.","prep_b":"Ontwerp drie voorzieningen voor een vriendelijke toekomststad, zoals een gratis park, een rustige bibliotheek en een kunstplein. Schrijf er één speciale stadsregel bij.","finale_together":"Leg beide ontwerpen naast elkaar en verbind de buurten met straten. Bepaal waar jullie eerste date in de droomstad zou zijn en teken die plek erbij.","finale_remote":"Toon beide plattegronden via video, voeg de buurten digitaal samen en maak één route van de ene favoriete plek naar de andere."},{"idx":15,"title":"Sterrenpoortceremonie","prep_a":"Teken een sterrenkaart met vijf fictieve sterrenbeelden. Markeer er één als de sleutel tot de verborgen poort en schrijf een kort raadsel voor de ander.","prep_b":"Maak een papieren poortsymbool, bedenk een zachte lichtceremonie met veilige LED-verlichting of een tekening en schrijf een openingsboodschap.","finale_together":"Los het sterrenraadsel op, open samen de papieren poort en spreek de openingsboodschap uit. Maak een gezamenlijke foto van het nieuwe sterrensymbool.","finale_remote":"Gebruik videobellen om de sterrenkaart te tonen. De ander lost het raadsel op en onthult het poortsymbool, daarna maken jullie samen een digitale sterrenpoort."},{"idx":16,"title":"De Grote Galactische Quizshow","prep_a":"Maak vijf originele quizvragen over verzonnen planeten en ruimtewezens. Bij iedere vraag hoort een verrassend grappig antwoord.","prep_b":"Schrijf vijf kosmische beeld- of geluidraadsels, bedenk een vriendelijk scorebord en maak een kleine symbolische trofee van papier.","finale_together":"Speel in twee rondes quizvragen en raadsels, wissel quizmasterrollen af en geef elkaar de trofee voor een grappige of creatieve poging.","finale_remote":"Speel de quiz via video met elk een eigen ronde. Houd de puntentelling speels; niemand hoeft een fout antwoord te verklaren."},{"idx":17,"title":"Onze Nacht Onder de Sterren","prep_a":"Teken drie sterrenbeelden die elk een mooie herinnering symboliseren. Schrijf op een kaartje één toekomstwens die je eventueel wilt delen.","prep_b":"Maak een warme, veilige avondhoek met dekens of een drankje en bereid een kort oorspronkelijk gedichtje of een zacht verhaaltje voor.","finale_together":"Maak het gezellig onder een echte of getekende sterrenhemel, onthul de drie sterrenbeelden en lees vrijwillig de wens en het gedicht voor. Sluit af met een rustig moment.","finale_remote":"Maak op beide locaties een rustige sterrensfeer en toon via video elkaars sterrenbeelden. Lees een gedicht voor en sluit samen af met één minuut stilte."},{"idx":18,"title":"Het Eeuwige Avontuur","prep_a":"Schrijf drie hoogtepunten van jullie gezamenlijke spelreis op kleine kaartjes. Maak een tekening van één moment dat je nog eens zou willen beleven.","prep_b":"Bedenk drie compleet nieuwe, vrijblijvende avonturen voor later. Maak voor ieder een mini-uitnodiging en een symbolische sleutel voor een volgende wereld.","finale_together":"Leg de herinneringskaartjes naast de nieuwe uitnodigingen en kies samen welk volgend avontuur het beste bij jullie past. Sluit af met een symbolische sleuteloverdracht en een foto.","finale_remote":"Deel via video de drie hoogtepunten en nieuwe uitnodigingen. Kies samen een toekomstig avontuur, maak een gezamenlijke digitale sleutel en bewaar de collage."}]$US_TWO_SUPER$::jsonb)
AS x(idx smallint,title text,prep_a text,prep_b text,finale_together text,finale_remote text)
ON CONFLICT (idx) DO NOTHING;

CREATE OR REPLACE FUNCTION us_two_private.seed_superdate(p_pair uuid, p_cell integer)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $US_TWO_FUNCTION$
DECLARE
 v_a uuid;
 v_idx integer;
 v_t us_two_private.quest_superdate_templates%rowtype;
BEGIN
 IF p_pair IS NULL OR p_cell IS NULL OR p_cell <= 0 OR p_cell % 20 <> 0 THEN
   RAISE EXCEPTION 'invalid_milestone' USING errcode='22023';
 END IF;
 SELECT user_id INTO v_a FROM public.us_members
 WHERE couple_id=p_pair ORDER BY joined_at,user_id LIMIT 1;
 IF v_a IS NULL OR
    (SELECT count(*) FROM public.us_members WHERE couple_id=p_pair)<>2
 THEN RAISE EXCEPTION 'pair_not_ready' USING errcode='22023'; END IF;
 v_idx:=((p_cell/20-1)%18)+1;
 SELECT * INTO v_t FROM us_two_private.quest_superdate_templates WHERE idx=v_idx;
 IF NOT FOUND THEN RAISE EXCEPTION 'superdate_template_missing' USING errcode='22023'; END IF;
 INSERT INTO public.us_quest_superdates
 (couple_id,cell,title,finale_remote,finale_together,user_a,prep_a,prep_b,prep_until)
 VALUES
 (p_pair,p_cell,v_t.title,v_t.finale_remote,v_t.finale_together,v_a,v_t.prep_a,v_t.prep_b,now()+interval '72 hours')
 ON CONFLICT DO NOTHING;
END
$US_TWO_FUNCTION$;

DO $US_TWO_AUDIT$
BEGIN
 IF (SELECT count(*) FROM us_two_private.quest_superdate_templates)<>18 THEN
   RAISE EXCEPTION 'Expected eighteen unique superdate templates';
 END IF;
 IF EXISTS(SELECT 1 FROM us_two_private.quest_superdate_templates
   WHERE length(trim(prep_a))<100 OR length(trim(prep_b))<100 OR
   length(trim(finale_remote))<100 OR length(trim(finale_together))<100)
 THEN RAISE EXCEPTION 'Superdate content incomplete'; END IF;
END
$US_TWO_AUDIT$;
